  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Linezolid, the closest oxazolidinone analogue (Morgan 0.4507), has essentially complete absolute oral bioavailability in humans (~100%), directly supporting F≥20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Delpazolid, another oxazolidinone, showed 99.75% absolute oral bioavailability after a single 800 mg oral dose in humans, supporting high F for the oxazolidinone class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Contezolid, a more polar/substituted oxazolidinone, had absolute bioavailability of 0.64 in healthy subjects, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "YH4808, a thiomorpholine-containing oxazolidinone, had low absolute bioavailability (10.1%), but its thiomorpholine and acetamide differ from the query's morpholinone and thiophene amide, limiting transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C23"],
      "claim": "Cadazolid, a gut-restricted non-absorbed oxazolidinone-quinolone hybrid, had very low F; its design intent and low similarity make it weak contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is an oxazolidinone with a morpholin-3-one N-aryl and 5-chlorothiophene carboxamide. The closest high-quality analogue linezolid has near-complete oral bioavailability, and other oxazolidinones (delpazolid, contezolid) also exceed 20%. The only low-F oxazolidinone (YH4808) is less similar and differs in key heterocycle/side chain; its low F does not override the consistent high-F pattern. Physicochemical properties are favorable. Prediction: high.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule itself.",
    "The mechanism of YH4808's low F is not explained; its transferability to the morpholinone/thiophene amide query is uncertain.",
    "No human PK data for posizolid/AZD5847 (if the query is that compound) are included in the provided evidence.",
    "Solubility and first-pass metabolism are not experimentally measured for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

